// HasWatchlistItems applies the HasEdge predicate on the "watchlistItems" edge.
func HasWatchlistItems() predicate.QuantInstrument {
	return predicate.QuantInstrument(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, WatchlistItemsTable, WatchlistItemsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasWatchlistItemsWith applies the HasEdge predicate on the "watchlistItems" edge with a given conditions (other predicates).
func HasWatchlistItemsWith(preds ...predicate.QuantWatchlistItem) predicate.QuantInstrument {
	return predicate.QuantInstrument(func(s *sql.Selector) {
		step := newWatchlistItemsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

